def place_grocery_order(data: Dict[str, Any], store_id: str, items: List[Dict[str, Any]],
                        delivery_address: Dict[str, Any], delivery_window: Dict[str, str],
                        special_instructions: Optional[str] = None,
                        tip_amount: Optional[float] = 5.0) -> str:
    """
    Place a grocery delivery order from a store.

    Args:
        data: The data dictionary
        store_id: ID of the grocery store to order from
        items: List of grocery items to order with quantities
        delivery_address: Address for delivery
        delivery_window: Preferred delivery time window with 'start' and 'end' times
        special_instructions: Special instructions for the delivery
        tip_amount: Fixed tip amount in dollars (not percentage)

    Returns:
        A JSON string with the result of the operation
    """
    # Input validation
    if not store_id:
        return json.dumps({
            "success": False,
            "message": "Store ID is required"
        })

    if not items or len(items) == 0:
        return json.dumps({
            "success": False,
            "message": "At least one item is required"
        })

    if not delivery_address:
        return json.dumps({
            "success": False,
            "message": "Delivery address is required"
        })

    if not delivery_window or not delivery_window.get("start") or not delivery_window.get("end"):
        return json.dumps({
            "success": False,
            "message": "Valid delivery window with start and end times is required"
        })

    if tip_amount is not None and (tip_amount < 0 or tip_amount > 50):
        return json.dumps({
            "success": False,
            "message": "Tip amount must be between 0 and 50 dollars"
        })

    # Check if the current user is set
    current_user = data.get("current_user")
    if not current_user:
        return json.dumps({
            "success": False,
            "message": "No user is currently selected"
        })

    # Find the grocery store
    store = find_store_by_id(data, store_id)
    if not store:
        return json.dumps({
            "success": False,
            "message": f"Grocery store with ID '{store_id}' not found"
        })

    if not store.get("delivery_available", False):
        return json.dumps({
            "success": False,
            "message": f"Store '{store.get('name')}' does not offer delivery"
        })

    # Validate items and calculate subtotal
    valid_items = []
    subtotal = 0.0
    inventory = store.get("inventory", [])
    inventory_dict = {item["item_id"]: item for item in inventory}

    for order_item in items:
        item_id = order_item.get("item_id")
        quantity = order_item.get("quantity", 1)

        if not item_id:
            return json.dumps({
                "success": False,
                "message": "Item ID is required for each item"
            })

        if quantity <= 0:
            return json.dumps({
                "success": False,
                "message": f"Quantity must be positive for item ID '{item_id}'"
            })

        inventory_item = inventory_dict.get(item_id)
        if not inventory_item:
            return json.dumps({
                "success": False,
                "message": f"Item with ID '{item_id}' not found in the store's inventory"
            })

        # Check if item is in stock
        if inventory_item.get("stock_count", 0) < quantity:
            return json.dumps({
                "success": False,
                "message": f"Insufficient stock for item '{inventory_item.get('name')}'. Only {inventory_item.get('stock_count')} available."
            })

        # Calculate item total
        item_price = inventory_item.get("price", 0) * quantity
        subtotal += item_price

        # Add to valid items list
        valid_items.append({
            "item_id": item_id,
            "name": inventory_item.get("name"),
            "quantity": quantity,
            "price": item_price,
            "substitution_preferences": order_item.get("substitution_preferences", "no_substitutions")
        })

    # Calculate taxes, delivery fee, and total
    tax_rate = 0.0625  # 6.25% tax rate for groceries (different from restaurant food)
    taxes = round(subtotal * tax_rate, 2)

    # Grocery delivery fees are based on order size and delivery window
    if subtotal >= 100:
        delivery_fee = 0.00  # Free delivery for orders over $100
    else:
        delivery_fee = 9.99  # Standard delivery fee

    # Add rush fee for same-day delivery windows
    current_date = datetime.now().strftime("%Y-%m-%d")
    if delivery_window.get("start", "").startswith(current_date):
        delivery_fee += 4.99  # Rush delivery fee

    total = subtotal + taxes + delivery_fee + (tip_amount if tip_amount is not None else 0.0)

    # Generate a unique order ID
    order_id = generate_grocery_order_id()

    # Create the new order
    current_time = get_current_timestamp()
    new_order = {
        "order_id": order_id,
        "user_id": current_user,
        "store_id": store_id,
        "order_time": current_time,
        "delivery_address": delivery_address,
        "delivery_window": delivery_window,
        "items": valid_items,
        "payment": {
            "subtotal": round(subtotal, 2),
            "tax": taxes,
            "delivery_fee": delivery_fee,
            "tip": tip_amount if tip_amount is not None else 0.0,
            "total": round(total, 2)
        },
        "status": "processing",
        "status_updates": [
            {
                "status": "processing",
                "timestamp": current_time
            }
        ],
        "shopper_info": None,
        "delivery_notes": special_instructions or ""
    }

    # Add order to data
    if "grocery_orders" not in data:
        data["grocery_orders"] = []

    data["grocery_orders"].append(new_order)

    # Update inventory stock counts
    for item in valid_items:
        inventory_item = inventory_dict.get(item["item_id"])
        if inventory_item:
            inventory_item["stock_count"] -= item["quantity"]

    # Success response
    return json.dumps({
        "success": True,
        "order_id": order_id,
        "store_name": store.get("name"),
        "order_time": current_time,
        "delivery_window": delivery_window,
        "status": "processing",
        "items_count": len(valid_items),
        "subtotal": round(subtotal, 2),
        "tax": taxes,
        "delivery_fee": delivery_fee,
        "tip": tip_amount if tip_amount is not None else 0.0,
        "total": round(total, 2),
        "message": "Your grocery order has been placed successfully"
    })
```

