# Developer intends to order groceries but uses the restaurant delivery function
# This will fail or produce unexpected results

# What the developer intended to do (grocery order with delivery window)
place_grocery_order(
    data=app_data,
    store_id="grocery123",
    items=[
        {"item_id": "milk001", "quantity": 2, "substitution_preferences": "similar_items"},
        {"item_id": "bread002", "quantity": 1, "substitution_preferences": "no_substitutions"}
    ],
    delivery_address={
