    },
    delivery_window={"start": "2023-10-15T14:00:00", "end": "2023-10-15T16:00:00"},
    tip_amount=7.50
)

# What the developer mistakenly does (using restaurant delivery function)
place_delivery_order(
    data=app_data,
    restaurant_id="grocery123",  # Using store_id as restaurant_id
    items=[
        {"item_id": "milk001", "quantity": 2, "substitution_preferences": "similar_items"},  # substitution_preferences is ignored
        {"item_id": "bread002", "quantity": 1, "substitution_preferences": "no_substitutions"}  # substitution_preferences is ignored
    ],
    delivery_address={
